WorkflowManager workflowManager = (WorkflowManager) AppUtil.getApplicationContext().getBean("workflowManager");

int size = 0;
size = workflowManager.getAssignmentSize(true, "appcenter:latest:inscription_formation");

int other_status_count = 0;
int count_meme_etab = 0;
int valide_count = 0;
DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
Connection con = null;
PreparedStatement stmtInsert = null;
ResultSet rs = null;

FormRowSet f = new FormRowSet();
f.setMultiRow(true);
FormRow r1 = new FormRow();

String createdBy = "#currentUser.username#";
String etab = "#form.inscription_ecole.etablissement#";
String formation = "#form.inscription_ecole.formation#";
String delais = "#form.delais.nombre_demandes_insc[delais_id]#"; // Ensure this syntax works in your framework
int delais_int = Integer.valueOf(delais); // Capitalize "Integer"

try {
    con = ds.getConnection();

    if (!con.isClosed()) {
        String selectSql = "SELECT SUM(CASE WHEN c_statut = 'Validé' THEN 1 ELSE 0 END) AS valide_count, "
                 + "SUM(CASE WHEN c_statut IN ('En cours de traitement', 'Accepté', 'Liste dattente') "
                 + "THEN 1 ELSE 0 END) AS other_status_count, "
                 + "SUM(CASE WHEN c_statut IN ('En cours de traitement', 'Accepté', 'Liste dattente','Refusé') AND c_etablissement = ? AND c_formation = ?"
                 + "THEN 1 ELSE 0 END) AS count_meme_etab "
                 + "FROM jwdb.app_fd_inscription_ecole WHERE createdBy = ?;";

        stmtInsert = con.prepareStatement(selectSql);
        stmtInsert.setString(1, etab);  // Safe parameter substitution
        stmtInsert.setString(2, formation);  // Safe parameter substitution
        stmtInsert.setString(3, createdBy);  // Safe parameter substitution
        
        rs = stmtInsert.executeQuery();

        if (rs.next()) {
            valide_count = rs.getInt("valide_count");
            other_status_count = rs.getInt("other_status_count");
            count_meme_etab = rs.getInt("count_meme_etab");
        }
    }
} catch (SQLException e) {
    LogUtil.info("error get DAO", e.getMessage());
} finally {
    try {
        if (rs != null) rs.close();
        if (stmtInsert != null) stmtInsert.close();
        if (con != null) con.close();
    } catch (SQLException ex) {
        LogUtil.error("Error closing resources", ex);
    }
}


String habilitation = "#form.habilitation.habilitaion_check[{form.inscription_ecole.formation};{form.inscription_ecole.id_etablissement}]#";
String currentDate = "#date.yyyy#";
String habilitation_date = "#form.habilitation.annee_fin[{form.inscription_ecole.formation};{form.inscription_ecole.id_etablissement}]#";
String niv = "#form.inscription_ecole.niveau#";


if (count_meme_etab != 0 || other_status_count >= delais_int || size >= delais_int) {
    r1.put("verification_process", "false");
}
else if (habilitation.equals("oui") && 
         ( (currentDate.compareTo(habilitation_date) > 0 && 
           (Integer.parseInt(currentDate) - Integer.parseInt(habilitation_date)) >= Integer.parseInt(niv)))) {
    r1.put("verification_process", "habilitation");
}


f.add(r1);
